import {SEAM_PINS as P} from './pins.mjs';import {createSeamRepairLayer} from './layer.mjs';
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const oldRects=[[3526,0,3590,360],[3529,367,3654,451],[3526,460,3590,800],[3526,1130,3590,1320]],plateRect=[948,99,1065,679];
export async function loadSeamRepair({fetcher=fetch,decode=b=>createImageBitmap(new Blob([b])),crop=(im,x,y,w,h)=>createImageBitmap(im,x,y,w,h),signal}={}){const held=new Set(),cleanupErrors=[];let disposed=false,layer;const check=()=>{if(signal?.aborted)throw Error('SEAM_ABORTED')},release=im=>{if(!held.delete(im))return;try{im.close?.()}catch(e){cleanupErrors.push(e)}},cleanup=()=>{for(const im of [...held])release(im)};
 try{const groups=[];for(const [name,width,height,rects]of [['old-g1-original.png',4812,1719,oldRects],['new-seam-plate-original.png',1672,941,[plateRect]]]){check();const r=await fetcher(new URL('./assets/'+name,import.meta.url),{signal});if(!r.ok)throw Error('SEAM_INPUT_MISSING');const b=new Uint8Array(await r.arrayBuffer());check();if(b.length!==P[name].bytes||await hash(b)!==P[name].sha256)throw Error('SEAM_INPUT_PIN');const full=await decode(b);held.add(full);check();if(full.width!==width||full.height!==height)throw Error('SEAM_IMAGE_DIMENSIONS');const pieces=[];for(const[x,y,right,bottom]of rects){check();const part=await crop(full,x,y,right-x,bottom-y);held.add(part);check();if(part===full||part.width!==right-x||part.height!==bottom-y)throw Error('SEAM_CROP_DIMENSIONS');pieces.push(part)}release(full);groups.push(pieces)}layer=createSeamRepairLayer({oldCrops:groups[0],plate:groups[1][0],plateSourceRect:plateRect});return Object.freeze({draw:layer.draw,cleanupErrors,dispose(){if(disposed)return;disposed=true;layer.dispose();cleanup()}})}catch(e){layer?.dispose();cleanup();throw e}}
